def build_agent(sandbox):
    # Lower beams (small particle separator)
    lower_beams = []
    x_positions = [5.24, 5.69, 6.14, 6.49]  # Ensures all vertices are within build zone x=[5.20, 6.90]
    for x in x_positions:
        bar = sandbox.add_static_beam(x, 1.92, 0.08, 0.3, density=78.125)
        sandbox.set_material_properties(bar, restitution=0.0)
        lower_beams.append(bar)
    # Upper beam (medium particle separator)
    upper_beam = sandbox.add_static_beam(5.70, 2.22, 1.0, 0.23, density=78.125)
    sandbox.set_material_properties(upper_beam, restitution=0.0)
    return lower_beams[0]  # Return the first lower beam as the main structural component

def agent_action(sandbox, agent_body, step_count):
    # Apply forces to guide particles into their target zones
    if step_count % 32 != 0:
        return
    # Push small particles down into the small zone
    for p in sandbox.get_particles_small():
        if p.active and p.position.y > 1.92:
            sandbox.apply_force(p, (0, -30.0))
    # Push medium particles up into the sieve band
    for p in sandbox.get_particles_medium():
        if p.active and p.position.y > 2.52:
            sandbox.apply_force(p, (0, -25.5))
    # Retain large particles above the sieve band
    for p in sandbox.get_particles_large():
        if p.active and p.position.y < 2.52:
            sandbox.apply_force(p, (0, -15.0))
